// Database Migration Script
// This script reads SQL files from the ./migrations/ directory and logs the filenames in the order they would be applied.

const fs = require('fs');
const path = require('path');

// Path to the migrations directory
const MIGRATIONS_DIR = './migrations';

// Function to read and sort migration files
function readMigrations() {
    // Check if the migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
        console.log(`Migrations directory does not exist: ${MIGRATIONS_DIR}`);
        return;
    }

    // Read the contents of the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter out non-SQL files and sort them
    const sqlFiles = files
        .filter(file => path.extname(file).toLowerCase() === '.sql')
        .sort((a, b) => a.localeCompare(b));

    // Log the filenames in order
    console.log('Migrations to apply (in order):');
    sqlFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });
}

// Execute the function
readMigrations();

