// Function to read and sort migration files
function getMigrationFiles() {
    try {
        // Read the files in the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter and sort the SQL files
        const migrationFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort();

        return migrationFiles;
    } catch (error) {
        console.error('Error reading migration files:', error.message);
        return [];
    }
}

// Function to log the migration files
function logMigrationFiles(migrationFiles) {
    if (migrationFiles.length === 0) {
        console.log('No migration files found.');
        return;
    }

    console.log('Migration files to apply (in order):');
    migrationFiles.forEach(file => {
        console.log(`- ${file}`);
    });
}

// Main function
function main() {
    const migrationFiles = getMigrationFiles();
    logMigrationFiles(migrationFiles);
}

// Run the script
main();

