// migrate.js - A simple database migration script
// This script reads SQL files from the ./migrations/ directory
// and logs each filename in the order they would be applied.

const fs = require('fs');
const path = require('path');

// Directory containing SQL migration files
const migrationsDir = './migrations/';

// Function to read and list migration files in order
function listMigrations() {
    try {
        // Check if the migrations directory exists
        if (!fs.existsSync(migrationsDir)) {
            console.log(`Migrations directory does not exist: ${migrationsDir}`);
            return;
        }

        // Read all files in the migrations directory
        const files = fs.readdirSync(migrationsDir);

        // Filter and sort SQL files (assuming a naming convention like `001_create_table.sql`)
        const migrationFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort();

        // Log each migration file in order
        console.log('Migration files to be applied in order:');
        migrationFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file}`);
        });

        if (migrationFiles.length === 0) {
            console.log('No migration files found in the directory.');
        }
    } catch (err) {
        console.error('Error reading migration files:', err);
    }
}

// Execute the function
listMigrations();

