/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory and logs each filename
 * in the order they would be applied. The files are sorted alphabetically by filename.
 */

const fs = require('fs');
const path = require('path');

// Directory containing migration SQL files
const MIGRATIONS_DIR = './migrations';

// Function to read migration files and log them in order
function logMigrations() {
    // Check if the migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
        console.log(`Directory '${MIGRATIONS_DIR}' does not exist.`);
        return;
    }

    // Read the contents of the migrations directory
    fs.readdir(MIGRATIONS_DIR, (err, files) => {
        if (err) {
            console.error('Error reading migrations directory:', err);
            return;
        }

        // Filter out non-SQL files
        const sqlFiles = files.filter(file => path.extname(file).toLowerCase() === '.sql');

        // Sort files alphabetically to ensure order
        sqlFiles.sort();

        if (sqlFiles.length === 0) {
            console.log('No migration files found.');
            return;
        }

        // Log each SQL file in order
        console.log('Migration files to apply in order:');
        sqlFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file}`);
        });
    });
}

// Execute the function
logMigrations();

