#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const migrationsDir = './migrations';

// Function to read SQL files from migrations directory
function readMigrationFiles() {
  try {
    fs.accessSync(migrationsDir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`Migrations directory does not exist: ${migrationsDir}`);
      process.exit(1);
    }
  }

  const files = fs.readdirSync(migrationsDir);
  const migrationFiles = files.filter(file => file.endsWith('.sql'));

  if (migrationFiles.length === 0) {
    console.log('No SQL migration files found in migrations directory.');
    return [];
  }

  return migrationFiles.sort();
}

// Function to log the migration files
function logMigrationFiles(migrationFiles) {
  console.log('The following migration files will be applied in order:');
  migrationFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });
}

// Main function
function main() {
  const migrationFiles = readMigrationFiles();
  if (migrationFiles.length > 0) {
    logMigrationFiles(migrationFiles);
  }
}

main();

